## 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>

#define INF (1LL << 60)

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    long long *A = (long long *) malloc((N + 1) * sizeof(long long));
    long long *ans = (long long *) malloc((N + 1) * sizeof(long long));

    for (int i = 1; i <= N; i++) {
        scanf("%lld", &A[i]);
    }

    long long best = INF;

    // Passagem da esquerda para a direita
    for (int i = 1; i <= N; i++) {
        if (A[i] != -1) {
            long long val = A[i] - i;
            if (val < best) best = val;
        }

        if (best != INF) {
            ans[i] = i + best;
        } else {
            ans[i] = INF;
        }
    }

    best = INF;

    // Passagem da direita para a esquerda
    for (int i = N; i >= 1; i--) {
        if (A[i] != -1) {
            long long val = A[i] + i;
            if (val < best) best = val;
        }

        if (best != INF) {
            long long right = -i + best;
            if (right < ans[i]) {
                ans[i] = right;
            }
        }
    }

    for (int i = 1; i <= N; i++) {
        printf("%lld", ans[i]);
        if (i < N) putchar(' ');
    }
    putchar('\n');

    free(A);
    free(ans);

    return 0;
}
```

